{
  "microtasks": [
    {
      "id": 1,
      "description": "Search academic databases using keywords 'procrastination', 'self-regulation', and 'college students' to gather an initial pool of 10-15 peer-reviewed articles.",
      "prerequisites": []
    },
    {
      "id": 2,
      "description": "Read the abstracts of the gathered articles to identify recurring sub-themes, such as emotional regulation, digital distractions, or intervention strategies.",
      "prerequisites": [1]
    },
    {
      "id": 3,
      "description": "Draft a list of three potential narrow research questions or angles based on the identified sub-themes.",
      "prerequisites": [2]
    },
    {
      "id": 4,
      "description": "Conduct a preliminary search for each of the three potential angles to verify that sufficient literature exists for each.",
      "prerequisites": [3]
    },
    {
      "id": 5,
      "description": "Select the final research question or angle based on source availability and academic interest.",
      "prerequisites": [4]
    },
    {
      "id": 6,
      "description": "Draft a preliminary thesis statement or core research objective addressing the selected angle.",
      "prerequisites": [5]
    },
    {
      "id": 7,
      "description": "Create a structural outline for the research paper based on the chosen thesis statement.",
      "prerequisites": [6]
    }
  ]
}
